<script setup lang="ts">
import { onMounted, onUnmounted, reactive, ref } from 'vue'
import { gatewayUrl, refreshAccessToken } from '@/api/authApi'
import { setAuth } from '@/services/authState'
import { readFeature, writeFeature, featureError, type Profile, type Page } from '@/services/additionalFeatures'
import { passwordHint, validPassword } from '@/services/passwordPolicy'
import OpsPager from '@/components/operations/OpsPager.vue'
import '@/components/operations/operations.css'
interface Login { id: number; method: string; address: string; agent: string; createdAt: string }
const profile = ref<Profile>(), security = ref({ enabled: false, backupCodes: 0 }), history = ref<Page<Login>>({ content: [], number: 0, totalPages: 0, totalElements: 0 })
const changing = reactive({ currentPassword: '', password: '', confirmPassword: '' }), proof = reactive({ currentPassword: '', code: '' })
const setup = ref<{ secret: string; uri: string; expiresAt: number }>(), backupCodes = ref<string[]>([]), busy = ref(false), error = ref(''), message = ref(''), signedOut = ref(false)
async function load(page = 0) { try { const [p,s,h] = await Promise.all([readFeature<Profile>('/api/users/me/profile'),readFeature<typeof security.value>('/api/users/me/security'),readFeature<Page<Login>>('/api/users/me/logins',{page})]); profile.value=p;security.value=s;history.value=h } catch(cause){error.value=featureError(cause)} }
async function act(work: () => Promise<void>) { if(busy.value)return;busy.value=true;error.value='';message.value='';try{await work()}catch(cause){error.value=featureError(cause)}finally{busy.value=false} }
const expireLocal = () => { signedOut.value=true;window.dispatchEvent(new Event('auth:expired'));setup.value=undefined;proof.currentPassword='';proof.code='' }
const save = () => act(async()=>{profile.value=(await gatewayUrl.put<Profile>('/api/users/me/profile',profile.value)).data;await refreshAccessToken();await setAuth();message.value='Đã lưu hồ sơ.'})
const changePassword = () => act(async()=>{if(!validPassword(changing.password)||changing.password!==changing.confirmPassword)throw new Error(passwordHint);await writeFeature('/api/users/me/change-password',changing);changing.currentPassword='';changing.password='';changing.confirmPassword='';expireLocal();message.value='Đã đổi mật khẩu và thu hồi phiên. Vui lòng đăng nhập lại.'})
const beginMfa = () => act(async()=>{setup.value=await writeFeature('/api/users/me/mfa/setup',proof);message.value='Thêm tài khoản trong ứng dụng tạo mã bằng khóa bên dưới, rồi nhập mã 6 chữ số.'})
const enable = () => act(async()=>{backupCodes.value=await writeFeature<string[]>('/api/users/me/mfa/enable',{code:proof.code});expireLocal();message.value='Đã bật xác thực hai bước. Lưu mã dự phòng trước khi đăng nhập lại.'})
const disable = () => act(async()=>{await writeFeature('/api/users/me/mfa/disable',proof);expireLocal();message.value='Đã tắt xác thực hai bước. Đăng nhập lại để tiếp tục.'})
const regenerate = () => act(async()=>{backupCodes.value=await writeFeature<string[]>('/api/users/me/mfa/backups',proof);proof.code='';message.value='Mã dự phòng cũ đã bị thay thế.'})
const revoke = () => act(async()=>{await writeFeature('/api/users/me/revoke-session');expireLocal();message.value='Đã thu hồi phiên hiện tại.'})
function downloadBackups(){const blob=new Blob(['Nihongo - mã dự phòng dùng một lần\n'+backupCodes.value.join('\n')],{type:'text/plain;charset=utf-8'}),url=URL.createObjectURL(blob),anchor=document.createElement('a');anchor.href=url;anchor.download='nihongo-backup-codes.txt';anchor.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
onMounted(()=>load());onUnmounted(()=>{setup.value=undefined;backupCodes.value=[];proof.currentPassword='';proof.code='';changing.currentPassword='';changing.password='';changing.confirmPassword=''})
</script>
<template><div class="ops-page"><header class="ops-heading"><h1>Tài khoản & bảo mật</h1><button v-if="!signedOut" class="ops-button secondary" :disabled="busy" @click="revoke">Thu hồi phiên đăng nhập</button></header><p v-if="error" class="ops-error" role="alert">{{ error }}</p><p v-if="message" class="ops-success" role="status">{{ message }}</p><section v-if="backupCodes.length" class="ops-panel"><h2>Mã dự phòng</h2><p>Mỗi mã dùng một lần. Lưu riêng ở nơi an toàn; không chia sẻ với người khác.</p><div class="ops-grid"><code v-for="code in backupCodes" :key="code">{{ code }}</code></div><button class="ops-button" @click="downloadBackups">Tải mã dự phòng</button></section><RouterLink v-if="signedOut" to="/login" class="ops-button">Đăng nhập lại</RouterLink><template v-else><form v-if="profile" class="ops-panel ops-form" @submit.prevent="save"><h2 class="wide">Hồ sơ</h2><label>Họ<input v-model="profile.firstName" required maxlength="100"></label><label>Tên<input v-model="profile.lastName" required maxlength="100"></label><label>Email<input :value="profile.email" readonly></label><label>Điện thoại<input v-model="profile.phone" maxlength="30"></label><label>Ngày sinh<input v-model="profile.birthday" type="date"></label><label class="wide">Địa chỉ<input v-model="profile.address" maxlength="255"></label><button class="ops-button" :disabled="busy">Lưu hồ sơ</button></form><form class="ops-panel ops-form" @submit.prevent="changePassword"><h2 class="wide">Đổi mật khẩu</h2><label class="wide">Mật khẩu hiện tại<input v-model="changing.currentPassword" type="password" autocomplete="current-password" required></label><label>Mật khẩu mới<input v-model="changing.password" type="password" autocomplete="new-password" required></label><label>Xác nhận<input v-model="changing.confirmPassword" type="password" autocomplete="new-password" required></label><p class="ops-muted wide">{{ passwordHint }}</p><button class="ops-button" :disabled="busy">Đổi mật khẩu</button></form><section class="ops-panel"><h2>Xác thực hai bước</h2><p>{{ security.enabled ? 'Đã bật' : 'Chưa bật' }} · {{ security.backupCodes }} mã dự phòng còn lại.</p><label>Mật khẩu hiện tại<input v-model="proof.currentPassword" type="password" autocomplete="current-password"></label><p v-if="setup"><strong>Khóa thiết lập: </strong><code>{{ setup.secret }}</code></p><label v-if="setup || security.enabled">Mã xác thực / mã dự phòng<input v-model="proof.code" autocomplete="one-time-code" maxlength="40"></label><div class="ops-actions"><button v-if="!security.enabled && !setup" class="ops-button" :disabled="busy || !proof.currentPassword" @click="beginMfa">Thiết lập xác thực hai bước</button><button v-if="setup" class="ops-button" :disabled="busy || !proof.code" @click="enable">Xác nhận và bật</button><template v-if="security.enabled"><button class="ops-button secondary" :disabled="busy || !proof.code || !proof.currentPassword" @click="regenerate">Tạo mã dự phòng mới</button><button class="ops-button danger" :disabled="busy || !proof.code || !proof.currentPassword" @click="disable">Tắt xác thực hai bước</button></template></div></section><section class="ops-panel"><h2>Lịch sử đăng nhập thành công</h2><p class="ops-muted">Lưu 90 ngày. Địa chỉ là kết nối mà dịch vụ xác thực quan sát; sau gateway có thể là IP gateway. Hệ thống giữ một phiên hoạt động cho mỗi tài khoản.</p><div class="ops-table-wrap"><table class="ops-table"><thead><tr><th>Thời gian</th><th>Cách đăng nhập</th><th>Địa chỉ</th><th>Trình duyệt</th></tr></thead><tbody><tr v-for="entry in history.content" :key="entry.id"><td>{{ new Date(entry.createdAt).toLocaleString('vi-VN') }}</td><td>{{ entry.method }}</td><td>{{ entry.address || 'Không có' }}</td><td>{{ entry.agent || 'Không có' }}</td></tr></tbody></table></div><OpsPager :page="history.number" :total-pages="history.totalPages" :total-elements="history.totalElements" :busy="busy" @change="load" /></section></template></div></template>
